import {ten04Data as data} from './ten04-data.js?v=20261028-ten04';
export {ten04Data} from './ten04-data.js?v=20261028-ten04';
const groups={
'national-parks':[['purposes','People and protection'],['erosion','Follow erosion'],['repair','Repair the route'],['tradeoffs','Compare proposals']],
'flood-risk':[['river','River defences'],['storage','Store and release'],['coast','Coastal realignment'],['evidence','Read event evidence']],
'climate-uncertainty':[['drivers','Three uncertainties'],['range','Read the projection'],['variability','Climate and weather'],['planning','Plan across scenarios']],
'climate-impacts':[['heat','Heat and water'],['runoff','Rain and runoff'],['coast','Sea level and habitat'],['opportunities','Conditional benefits']],
'climate-responses':[['mitigation','Reduce the driver'],['adaptation','Reduce exposure'],['scales','Local and national'],['monitor','Check outcomes']],
'enquiry-questions':[['chain','Build an enquiry'],['variables','Define what to measure'],['context','Match the field context'],['evidence','Choose evidence']],
'sampling-methods':[['convenience','Convenient sites'],['systematic','Regular intervals'],['stratified','Represent each zone'],['repeats','Accuracy and repeats']],
'presenting-data':[['map','Join records to a map'],['scatter','Compare two variables'],['bars','Compare categories'],['scale','Check the scale']],
'analysing-data':[['pattern','Pattern and exception'],['summary','Mean and range'],['explain','Test explanations'],['conclude','Bound the conclusion']],
'evaluating-enquiry':[['coverage','Improve coverage'],['sensitivity','Check sensitivity'],['triangulate','Compare sources'],['judgement','Judge confidence']]
};
export const ten04Views=Object.fromEntries(Object.entries(groups).map(([k,v])=>['dev-ten04-'+k,v]));
export const ten04Requirements=Object.fromEntries(Object.entries(ten04Views).map(([k,v])=>[k,v.map(x=>x[0])]));
export const ten04Animated=(k,v)=>({'national-parks':['erosion','repair'],'flood-risk':['river','storage','coast'],'climate-impacts':['heat','runoff','coast'],'climate-responses':['mitigation','adaptation']}[k.replace('dev-ten04-','')]||[]).includes(v);
export const sampleMean=xs=>xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;
export const sampleRange=xs=>xs.length?Math.max(...xs)-Math.min(...xs):null;
export const sampleMedian=xs=>{if(!xs.length)return null;const v=[...xs].sort((a,b)=>a-b),m=Math.floor(v.length/2);return v.length%2?v[m]:(v[m-1]+v[m])/2;};
const E=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const readable=s=>String(s).replace(/([a-z])(?=\d)/g,'$1 ').replace(/(?<=\d)(?=(?:m³|m\b|people|years|minutes|December|January))/g,' ');
const T=(x,y,s,z=12)=>`<text x="${x}" y="${y}" font-size="${z}">${E(readable(s))}</text>`;
const P=(d,c='#b8cdd0',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const R=(x,y,w,h,c='#35566b')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="${c}"/>`;
const D=(x,y,c='#edb396',r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f1e4ce"/>`;
const flow=(x,y,a,b,t,c='#b3d3db')=>P(`M${x} ${y}L${a} ${b}`)+D(x+(a-x)*t,y+(b-y)*t,c);
const box=(y,a,b)=>R(20,y,400,61)+T(32,y+23,a,14)+T(32,y+46,b,11);
const matrix=(title,rows)=>T(20,28,title,13)+rows.map(([a,b],i)=>box(60+92*i,a,b)).join('');
const F=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${E(c)}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${E(c)}</p>`;
const urls=Object.fromEntries(data.sources.map(s=>[s.key,s.url]));
const A=(k,s)=>`<a href="${E(urls[k])}" target="_blank" rel="noopener">${s}</a>`;
const spec='https://qualifications.pearson.com/content/dam/pdf/GCSE/Geography-A/2016/specification-and-sample-assessments/gcse-2016-l12-geography-a-spec.pdf';
const source={park:A('park','Lake District purposes and vision')+' · '+A('paths','Fix the Fells')+'. England case; purposes are not asserted identical across UK jurisdictions. Original diagrams simplify pressure and maintenance; not measured visitor flows, boundaries or recovery rates. Vision is an aim, not an achieved outcome.',flood:A('flood','Forest Research: Pickering')+' · '+A('coast','EA historical Medmerry account (2013/14)')+'. Pickering December2015 peak reduction15–20% is an event estimate, not a future guarantee. Medmerry page is an archived/withdrawn historical account, not current access guidance. Water paths, storage geometry and timing schematic; storage delays water, it does not destroy it. Residual risk remains.',climate:A('climate','UK first Biennial Transparency Report2024, section2.5.2.1')+'. UKCP conditional medium-emissions UK annual mean change2080–2100 relative1981–2000: median2.3°C;10th–90th percentiles1.1–3.6°C. Not absolute daily temperatures, local design values or guaranteed limits. Illustrations of mechanisms are not measured impact forecasts.',response:A('national','NAP3 adaptation explanation2023–2028')+' · '+A('local','London Cool spaces, summer2026')+'. Programme intentions are not completed outcomes. NAP includes England policies and reserved responsibilities; devolved administrations have adaptation programmes. London availability is seasonal and submission-dependent, not a medical service or year-round opening guarantee.',field:`<a href="${spec}" target="_blank" rel="noopener">Pearson1GA0 Issue5, printed27–30</a>. All site positions, scores, counts and repeats here are invented teaching data, not measurements, actual sites or national statistics. Local grid in metres is not OS coordinates. Reading a map/graph or choosing a method does not establish student GIS operation, graph construction, extended written evaluation or the two required fieldwork occasions outside school grounds.`};
const S=k=>`<details class="geo-chart-values"><summary>Sources &amp; model limits</summary><p class="geo-caption">${source[k]}</p></details>`;
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data geo-water-data"><caption>${E(cap)}</caption><thead><tr>${heads.map(x=>`<th scope="col">${E(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${E(r[0])}</th>${r.slice(1).map(x=>`<td>${E(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
function grid(){let b=T(20,28,'SITE-ID JOIN · INVENTED LOCAL GRID',13)+T(20,49,'North ↑ · coordinates in metres, not OS references',10);for(let n=0;n<=4;n++){const x=60+n*80;b+=P(`M${x} 80V240`,'#688797',1)+T(x-10,261,n*100,10);}for(let n=0;n<=2;n++){const y=240-n*80;b+=P(`M60 ${y}H380`,'#688797',1)+T(26,y+4,n*100,10);}for(const[id,,score,e,n]of data.worked.sites){const x=60+e*.8,y=240-n*.8;b+=D(x,y,'#b2ccb6',7)+T(x-10,y-15,id,15)+T(x-14,y+28,'S:'+score,11);}return b+T(120,286,'Easting /m →',11)+T(20,318,'S = subjective noise score,0–20',12);}
function scatter(fresh=false){const rows=fresh?data.worked.independentSites:data.worked.sites;let b=T(20,28,'DISTANCE AND SCORE · INVENTED DATA',13)+T(20,50,'Subjective score /0–20 (not decibels)',11);for(let n=0;n<=20;n+=5){const y=275-n*10;b+=P(`M55 ${y}H400`,'#688797',1)+T(24,y+4,n,11);}b+=P('M55 70V275H400');for(const[id,d,s]of rows){const x=65+d*1.05,y=275-s*10;b+=D(x,y,'#b2ccb6',6)+T(x+10,y-7,id,12)+T(x-6,300,d,10);}return b+T(100,330,'Distance from road /m',12);}
function columns(vals,labels,unit,title){let b=T(20,28,title,13)+T(20,50,unit+' · zero baseline',11),max=Math.max(...vals)*1.2;for(let i=0;i<vals.length;i++){const x=45+i*90,h=vals[i]/max*180;b+=R(x,265-h,55,h,'#b2ccb6')+T(x+9,252-h,vals[i],15)+T(x,294,labels[i],11);}return b+P('M35 265H410');}
export function ten04Evidence(k){let b='',c='',heads=[],rows=[],s='field';
 if(k==='climate'){const[lo,mid,hi]=data.climate.annualWarmingC,x=n=>65+n*82;b=T(20,27,'UK ANNUAL TEMPERATURE CHANGE',13)+T(20,53,'Medium emissions ·2080–2100',13)+T(20,78,'Relative to1981–2000 · conditional projection',11)+P('M65 220H393');for(let n=0;n<=4;n++)b+=P(`M${x(n)} 213V227`)+T(x(n)-4,248,n,12);b+=P(`M${x(lo)} 161H${x(hi)}`,'#b2ccb6',10)+D(x(mid),161,'#edb396',8)+T(x(lo)-14,138,lo+'°C',13)+T(x(hi)-17,138,hi+'°C',13)+T(x(mid)-17,191,mid+'°C',13)+T(20,284,'10th–90th percentile interval · dot = median',11)+T(20,320,'Source: UK first BTR2024 · not observations',11);c='UK conditional annual warming: medium-emissions median2.3°C and10th–90th range1.1–3.6°C,2080–2100 relative1981–2000. A source interval, not guaranteed physical bounds.';rows=[['10th percentile',lo],['Median',mid],['90th percentile',hi]];heads=['Conditional statistic','Change /°C'];s='climate';}
 else if(k==='flood'){b=matrix('PICKERING · DECEMBER2015 EVENT ESTIMATE',[['Estimated peak-flow reduction','15–20% for the studied event'],['Combined management','Upstream measures + main storage area'],['Transfer to another storm?','Conditions and model assumptions matter']]);c='Forest Research estimates a15–20% peak-flow reduction for the December2015 event. No measured100m³/s peak is claimed; arithmetic questions may give a separate invented comparison peak.';heads=['Quantity','Source range'];rows=[['Estimated reduction /%', '15–20']];s='flood';}
 else if(k==='map'){b=grid();c='Invented local-grid site records: ID, coordinates in metres and subjective0–20 noise score. These are not real locations, decibels or an OS grid.';rows=data.worked.sites.map(([id,,v,e,n])=>[id,e,n,v]);heads=['SiteID','Easting /m','Northing /m','Score /0–20'];}
 else if(k==='scatter'){b=scatter(true);c='Fresh invented sitesP,Q,R,S at distances0,100,200,300m, with subjective0–20 noise scores14,11,7,9. Not decibel readings or a causal experiment.';rows=data.worked.independentSites;heads=['Site','Distance /m','Score /0–20'];}
 else if(k==='counts'){b=columns(data.worked.independentCounts,['P','Q','R','S'],'People per10minutes','FRESH COUNTS · INVENTED DATA');c='Four invented counts8,12,10,14people, each for10minutes. Equal duration permits this comparison; no actual village or representative sample is claimed.';rows=data.worked.independentCounts.map((n,i)=>[['P','Q','R','S'][i],n]);heads=['Site','People per10minutes'];}
 else return '';
 return F(b,c)+S(s)+table('Values with the displayed scope and units',heads,rows);
}
export function ten04Scene(k,v,t=0){if(!ten04Views[k])return '';if(!ten04Requirements[k].includes(v))v=ten04Requirements[k][0];const slug=k.replace('dev-ten04-','');t=ten04Animated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s=slug==='national-parks'?'park':slug==='flood-risk'?'flood':slug==='climate-responses'?'response':slug.startsWith('climate-')?'climate':'field';
 if(slug==='national-parks'){
 if(v==='purposes'){b=matrix('LAKE DISTRICT · ENGLAND CASE',[['Conserve landscape, wildlife and heritage','Protect the qualities people come to enjoy'],['Help people understand and enjoy','Access can create both benefits and pressures'],['Community wellbeing','Homes / farming / jobs / transport / services']]);c='Interacting purposes and community needs, not three independent scores. In this England case conservation has greater weight where the two purposes conflict.';}
 else if(v==='erosion'||v==='repair'){const repair=v==='repair';b=T(20,28,repair?'DURABLE ROUTE + MANAGED DRAINAGE':'BOOTS + RUNOFF → SOIL LOSS',13)+`<path d="M20 230L160 90L300 150L420 235V300H20Z" fill="#6f8b7c"/>`+P('M70 270L170 140L250 195L370 270',repair?'#d0c4a8':'#b08b70',repair?12:18+20*t)+flow(190,130,300,270,t,repair?'#b3d3db':'#dfae82')+flow(250,200,370,285,t)+D(70+100*t,270-130*t,'#f0e7d2',7)+T(20,321,repair?'Keep walkers on route; protect adjacent vegetation':'Bare ground can widen; sediment reaches streams',11);c=repair?'Illustrative path repair and drainage retain access while limiting trampling and sediment loss. Maintenance is needed; the loop is not a measured recovery rate.':'Illustrative repeated use and water move soil downslope. Path width and moving particles are symbolic, not measured erosion at a named site.';}
 else{b=matrix('COMPARE A PROPOSAL AGAINST ITS ALTERNATIVES',[['Benefits to people','Local housing / services / jobs / accessible visits'],['Landscape costs','Habitat / heritage / traffic / noise / water'],['Possible modifications','Siting / scale / transport / mitigation / monitoring']]);c='No single proposal is scored as automatically best. A defensible choice needs evidence on needs, effects and alternatives.';}}
 if(slug==='flood-risk'){
 if(v==='evidence')return ten04Evidence('flood');
 if(v==='river'){b=T(20,28,'RIVER WALLS: PROTECTION AND RESIDUAL RISK',12)+R(20,220,400,70,'#697f6d')+R(100,100,240,160,'#527c91')+P('M95 100V265M345 100V265','#e0cfab',9)+flow(220,95,220,280,t)+R(365,180,40,35,'#d5bfa5')+T(24,313,'Assess capacity, upkeep and downstream effects.',11);c='Illustrative channel between walls with a nearby property. Walls constrain water but can be exceeded; geometry and flows are not an engineering design.';}
 else if(v==='storage'){const f=t<.5?t*2:(1-t)*2;b=T(20,28,'STORE TEMPORARILY, THEN RELEASE',13)+P('M20 180H140L200 250H300L360 180H420','#a3b79a',8)+R(145,255-75*f,210,75*f,'#80a7b7')+flow(20,170,135,170,t)+flow(360,170,420,170,t*.6)+T(20,85,'Catchment measures + main storage',14)+T(175,225,'Storage',15)+T(20,310,'Water is delayed, not destroyed.',12)+T(20,331,'Filling / release are schematic; no mass-rate claim.',10);c='A temporary store fills and drains over the illustrative cycle. The outlet has a slower moving marker; marker speeds are not measured discharge or a validated flow balance.';}
 else{b=T(20,28,'REALIGN THE COASTAL DEFENCE',13)+R(20,80,120,200,'#527c91')+R(140,80,170,200,'#708c7b')+R(140,280-200*t,170,200*t,'#658e9e')+P('M140 80V150M140 210V280','#c9bca0',4)+P('M315 80V280','#e2cfa6',9)+flow(40,180,270,180,t)+R(355,155,45,45,'#d5bfa5')+T(20,310,'Sea → intertidal land → new inland defence',11)+T(20,332,'Schematic Medmerry mechanism, not a site map',10);c='Sea enters through a breach into land seaward of a relocated inland defence. Some land is deliberately allowed to flood; the new defence protects landward assets with residual risk.';}}
 if(slug==='climate-uncertainty'){
 if(v==='range')return ten04Evidence('climate');
 if(v==='drivers'){b=matrix('WHY MORE THAN ONE FUTURE?',[['Emissions scenario','Different future human activity and emissions'],['Climate model','Different representations of complex processes'],['Natural variability','Year-to-year and longer fluctuations remain']]);c='Three uncertainty sources, not equal numerical shares of uncertainty. Their importance varies by variable, place and timescale.';}
 else if(v==='variability'){const ys=[230,207,223,176,194,158,175,125];b=T(20,28,'TREND WITH YEAR-TO-YEAR VARIABILITY',13)+T(20,51,'Invented qualitative illustration · not observations',10)+P('M45 80V275H410')+P(ys.map((y,i)=>(i?'L':'M')+(55+i*47)+' '+y).join(' '),'#b2ccb6',3)+P('M55 240L384 130','#edb396',2)+T(20,306,'Individual cooler years can occur within warming.',11)+T(20,329,'No calendar years or measured temperature scale',10);c='Static conceptual illustration of variability around a longer-term tendency; not a measured historical record or model output. A single year does not establish or disprove a climate trend.';}
 else{b=matrix('ROBUST PLANNING',[['Test more than one scenario','Use relevant season, region and time horizon'],['Keep options adaptable','Staged investment / capacity / maintenance'],['Monitor and revisit','Compare observations with decision thresholds']]);c='Uncertainty calls for relevant evidence and review; it does not mean every outcome is equally likely or that action must wait for certainty.';}}
 if(slug==='climate-impacts'){
 if(v==='heat'){b=T(20,28,'HEAT + DRYNESS → PEOPLE AND HABITATS',12)+D(65,95,'#edb396',24)+R(230,130,75,110,'#a59486')+R(330,175,70,65,'#6e8d79')+flow(90,105,230,170,t,'#edb396')+flow(90,105,330,210,t,'#edb396')+T(225,115,'Buildings',12)+T(330,158,'Habitats',12)+T(20,275,'Heat exposure / water demand / soil moisture',11)+T(20,318,'Shade, health, support and water access vary.',11);c='Heat and dryness can stress people, water systems and habitats. Moving markers show causal pathways, not energy, measured temperatures or equal vulnerability.';}
 else if(v==='runoff'){b=T(20,28,'RAIN → RUNOFF → EXPOSED PLACES',13)+R(20,230,400,70,'#6f8b7c')+P('M20 230L210 260H420','#aac2ce',13)+R(300,180,55,55,'#d5bfa5')+flow(100,80,100,225,t)+flow(180,90,180,235,t)+flow(205,255,390,255,t)+T(20,315,'Soil saturation and surfaces affect infiltration.',11);c='Illustrative rainfall and connected runoff route. Actual flood depth depends on rainfall, soil, drainage, land use and defences; no event forecast is implied.';}
 else if(v==='coast'){b=T(20,28,'SEA-LEVEL RISE + FIXED LANDWARD BARRIER',12)+R(20,110,240,170,'#527c91')+R(140,220,120,60,'#b2ccb6')+R(20,220-65*t,240,65*t,'#81a5b5')+P('M265 90V280','#e2cfa6',10)+T(290,170,'Fixed',13)+T(290,195,'barrier',13)+T(20,315,'Habitat space can shrink without room to move.',11);c='Conceptual coastal squeeze: a rising tidal baseline can inundate habitat while a fixed barrier limits landward migration. Shapes and rise are not local projections.';}
 else{b=matrix('AN OPPORTUNITY NEEDS CONDITIONS',[['Longer growing season','Crop suitability / water / pests / heat stress'],['Warmer-weather tourism','Comfort / water / infrastructure / ecosystems'],['Compare people and places','Benefits and losses vary; adaptation matters']]);c='Possible opportunities do not establish a universal net gain. Assess linked constraints, unequal impacts and uncertainty.';}}
 if(slug==='climate-responses'){
 if(v==='mitigation'){b=T(20,28,'MITIGATION: LESS EMISSION AT SOURCE',13)+R(30,150,100,95)+R(310,130,95,115)+T(45,195,'Energy',16)+T(322,175,'Air',16)+flow(140,165,300,165,t,'#edb396')+P('M175 145L205 185M205 145L175 185','#b2ccb6',4)+T(20,285,'Efficiency / cleaner supply / lower-energy travel',11)+T(20,320,'Marker illustrates a pathway, not tonnes of CO₂.',11);c='Mitigation addresses the greenhouse-gas driver, for example reducing fossil-energy emissions. Symbolic pathway only, not a measured emissions saving or instant reversal of warming.';}
 else if(v==='adaptation'){b=T(20,28,'ADAPTATION: REDUCE HEAT EXPOSURE',13)+D(65,80,'#edb396',22)+R(210,145,85,110,'#a59486')+`<path d="M160 135Q225 80 320 135Z" fill="#b2ccb6"/>`+P('M170 135V255','#a8b49b',8)+flow(80,100,160,150,t,'#edb396')+flow(295,250,390,250,t)+T(325,210,'Access',13)+T(20,305,'Shade / indoor respite / accessible provision',11)+T(20,330,'No medical service or measured cooling implied',10);c='Shade and accessible respite can reduce exposure. Design, opening times, vulnerable users and maintenance matter; the diagram does not guarantee medical protection or a temperature reduction.';}
 else if(v==='scales'){b=matrix('LOCAL AND NATIONAL RESPONSES',[['London Cool spaces · summer2026','Seasonal respite provision / variable coverage'],['National NAP3 ·2023–2028','Adaptation actions across sectors; devolved roles too'],['Link resources to place','Funding / standards / local delivery / review']]);c='Two dated examples of action at different scales. Programme intentions do not establish completed resilience; London’s map is seasonal, not a current opening guarantee.';}
 else{b=matrix('OUTPUT IS NOT THE SAME AS OUTCOME',[['Delivered output','Spaces listed / trees planted / homes improved'],['Relevant outcome','Exposure / access / survival / energy emissions'],['Fair comparison','Weather / users / time / maintenance / distribution']]);c='Evaluate delivery and measured effects with appropriate comparators. An output count alone does not establish a climate benefit.';}}
 if(slug==='enquiry-questions'){
 if(v==='chain'){b=matrix('QUESTION → METHOD → EVIDENCE',[['Question: distance and perceived noise','Where? Which road? Which time window?'],['Prediction: scores may fall with distance','Theory informs an expectation, not a required result'],['Evidence: comparable observations','Record site / distance / scale / time / context']]);c='A worked enquiry-planning chain. The prediction is testable, not predetermined; perceived scores are not calibrated sound levels.';}
 else if(v==='variables'){b=matrix('OPERATIONAL DEFINITIONS',[['Compare: distance from a named road','Metres / defined origin / consistent method'],['Record: perceived noise score','Define0–20scale / duration / observer protocol'],['Consider other factors','Wind / buildings / traffic timing / other sources']]);c='Definitions make a question measurable. A subjective scoring scale remains different from a calibrated decibel measurement.';}
 else if(v==='context'){b=T(20,28,'EDEXCEL FIELDWORK CONTEXTS',13)+box(62,'One physical investigation','River channel change OR coastal landscape evidence')+box(157,'One human investigation','Central/inner urban change OR rural settlement change')+T(20,278,'Outside classroom AND school grounds',14)+T(20,316,'App preparation cannot establish participation.',11);c='The qualification requires contrasting physical and human fieldwork. The app does not replace school-organised physical investigations or verify participation.';}
 else{b=matrix('COMBINE EVIDENCE WITH A PURPOSE',[['Primary: your own observations','Counts / measurements / sketches / recorded views'],['Secondary: collected by others','Maps / census / historical records / earlier surveys'],['Check compatibility','Date / coverage / definitions / provenance']]);c='Primary and secondary describe collection provenance, not numerical versus descriptive data. Both need method and source evaluation.';}}
 if(slug==='sampling-methods'){
 if(['convenience','systematic','stratified'].includes(v)){b=T(20,28,v==='convenience'?'CONVENIENCE: ONLY EASY ROADSIDE SITES':v==='systematic'?'SYSTEMATIC: SITES AT REGULAR INTERVALS':'STRATIFIED: SAMPLE WITHIN EACH ZONE',12)+T(20,51,'Invented site frame · dots are proposed sample sites',10);for(let i=0;i<3;i++)b+=R(30+i*130,80,120,185,['#3c5c6c','#547466','#6b7f69'][i])+T(55+i*130,110,['Near','Middle','Far'][i],15);b+=P('M40 80V260','#e2cfa6',7);const pts=v==='convenience'?[[48,235],[65,235],[83,235],[100,235],[118,235],[135,235]]:v==='systematic'?[[65,145],[120,145],[175,145],[230,145],[285,145],[340,145]]:[[65,145],[110,205],[185,170],[220,225],[315,145],[355,210]];for(const[x,y]of pts)b+=D(x,y,'#edb396',6);b+=T(20,295,v==='convenience'?'Far and middle zones poorly represented':v==='systematic'?'Check periodic patterns and safe access':'Strata and allocation must suit the enquiry',12)+T(20,329,'Not a random draw or a claim of representativeness',10);c=v==='convenience'?'Convenient sample clusters along one road section and misses other zones. More dots there do not automatically fix coverage bias.':v==='systematic'?'Regularly spaced sites illustrate systematic sampling. An interval can miss patterns; do not enter unsafe sites to preserve spacing.':'Selected sites within each defined zone illustrate stratified coverage. Placement is illustrative, not a generated random sample or automatically optimal allocation.';}
 else{b=matrix('CONSISTENT IS NOT ALWAYS CORRECT',[['Reliable repeats','Similar readings under a consistent protocol'],['Accurate measurement','Close to true value; check calibration and units'],['Safe and ethical collection','Approved risk plan / consent / voluntary responses']]);c='A miscalibrated instrument may repeatedly give similar wrong readings. Repetition does not remove systematic bias; safety overrides a sampling schedule.';}}
 if(slug==='presenting-data'){
 if(v==='map')return ten04Evidence('map');
 if(v==='scatter'){b=scatter(false);c='Invented worked scores12,9,6,7 at0,100,200,300m. Scatter points compare two numerical variables and retain the last-site exception; scores are not decibels.';}
 else if(v==='bars'){b=columns([8,5,3],['Retail','Homes','Services'],'Number of premises','CATEGORIES · INVENTED LAND-USE COUNTS');c='Invented premises counts8retail,5homes,3services. Separate category bars use a zero baseline and do not imply an ordered continuous relationship.';}
 else{b=T(20,28,'SAME VALUES · DIFFERENT AXIS BASELINES',12);for(const[i,start]of[0,9].entries()){const x=35+i*205;b+=P(`M${x} 80V270H${x+155}`)+T(x,64,'Axis starts '+start,12);for(const[j,val]of[10,12].entries()){const h=(val-start)/(14-start)*170;b+=R(x+20+j*65,270-h,45,h,'#b2ccb6')+T(x+28+j*65,258-h,val,14);}b+=T(x-2,290,start,11);}b+=T(20,327,'Truncation changes appearance, not the values.',11);c='The same invented10and12 shown on zero and9-starting scales. A truncated axis can exaggerate apparent differences; explicit scale and purpose matter.';}}
 if(slug==='analysing-data'){
 if(v==='pattern'){b=scatter(false);c='Describe the overall decline and final-site rise using actual values. The four invented observations show association, not a universal cause.';}
 else if(v==='summary'){b=columns([12,9,6,7],['A','B','C','D'],'Subjective score /0–20','WORKED SUMMARY · INVENTED SCORES')+T(20,330,'Mean8.5 · range6 · retain the individual values',11);c='Worked calculation: sum34 /4 =8.5; maximum12 minus minimum6 =6. Summary statistics do not replace the pattern or exception.';}
 else if(v==='explain'){b=matrix('ASSOCIATION IS A START, NOT PROOF',[['Possible mechanism','Sound may weaken farther from a source'],['Alternative factors','Buildings / timing / wind / other sources / scoring'],['Test the explanation','Repeat / compare settings / use suitable context']]);c='Competing explanations require evidence. A scatter plot alone does not isolate the effect of distance.';}
 else{b=matrix('ANSWER + EVIDENCE + QUALIFICATION',[['Answer the actual question','Scores generally decline in these four observations'],['Quote evidence and exception','12 at0m →6 at200m →7 at300m'],['Bound the conclusion','Four sites / one survey window / subjective scale']]);c='A supported but limited conclusion, rather than confirmation at any cost. Theory can explain an observed pattern without proving a sole cause.';}}
 if(slug==='evaluating-enquiry'){
 if(v==='coverage'){b=matrix('LIMITATION → EFFECT → IMPROVEMENT',[['Only lunchtime counts','Commuters or evening users may be missed'],['Only easy roadside sites','Other neighbourhood conditions may be missed'],['Targeted improvement','Add comparable time periods and defined zones']]);c='Improve the specific source of uncertainty; do not assume that simply repeating one biased sample removes bias.';}
 else if(v==='sensitivity'){b=columns(data.worked.repeats,['Repeat1','Repeat2','Repeat3'],'Subjective score /0–20','CHECK AN UNUSUAL READING')+T(20,329,'Mean10 · median7 · investigate17, do not hide it',11);c='Invented6,7,17: mean10, median7. The unusual reading may be genuine or erroneous; check notes and method before a transparent exclusion decision.';}
 else if(v==='triangulate'){b=matrix('COMPARE INDEPENDENT, RELEVANT SOURCES',[['Your field evidence','Method / date / sample / locations / uncertainty'],['Secondary evidence','Who collected it? Date? Area? Same definitions?'],['Agreement or disagreement','Shared bias? Changed context? Further tests?']]);c='Triangulation can increase or challenge confidence, but apparent agreement from copied or incompatible sources is weak evidence.';}
 else{b=matrix('HOW FAR CAN THE CONCLUSION REACH?',[['Reliable within what scope?','These safe sites and recorded survey periods'],['What may change the answer?','Missing groups / variation / calibration / context'],['What would improve confidence?','Feasible targeted tests, not guaranteed confirmation']]);c='Evaluation links methods to the reach of a conclusion. Do not invent observations to cover inaccessible sites or claim these examples establish actual fieldwork.';}}
 return F(b,c)+S(s);
}
